import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'collection-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasIndex = 0;
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasW = 512;
  const atlasH = 320;

  const aspect = rect.w / rect.h;
  const planeHeight = 0.9;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const map = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const uOffset = rect.x / atlasW;
  const vOffset = 1.0 - (rect.y + rect.h) / atlasH;
  const uScale = rect.w / atlasW;
  const vScale = rect.h / atlasH;

  const uvNode = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));

  const material = new THREE.MeshBasicNodeMaterial();
  material.map = map;
  material.colorNode = texture(map, uvNode);
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'collection-card-1-plane';
  group.add(mesh);

  // Headline text: "Collection 1"
  const fontAtlas = ctx.fontAtlas;
  let textMesh = null;
  if (fontAtlas && fontAtlas.createText) {
    textMesh = fontAtlas.createText({
      text: 'Collection 1',
      font: 'display',
      weight: 400,
      size: 0.34,
      color: config.colors?.paper || '#e8ecf2',
      anchor: 'center',
    });
    textMesh.name = 'collection-card-1-headline';
    textMesh.position.set(0, -planeHeight / 2 - 0.15, 0.01);
    group.add(textMesh);
  }

  // Billboard toward camera each frame via onBeforeRender
  group.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
    group.onBeforeRender = null;
  };

  return group;
}
